const input = $json;

const mode = input.guardrail_mode === "output" ? "output" : "input";

const candidate =
  mode === "output"
    ? String(input.response ?? input.output ?? input.message ?? "").trim()
    : input.message;

const result = {
  ...input,
  guardrail_mode: mode,
  input_valid: false,
  guardrail_status: "BLOCKED",
  guardrail_decision: "BLOCKED",
  rejection_reason: null,
  secret_detected: false,
  pii_detected: false,
  requires_review: false,
  guardrail_state: {
    stage: mode,
    checked: true,
    passed: false,
    blocked: false,
    review_required: false
  }
};

// --------------------------------------------------
// 1. Validate input
// --------------------------------------------------

if (typeof candidate !== "string" || !candidate.trim()) {
  result.rejection_reason =
    mode === "input"
      ? "Message is missing or is not text."
      : "Generated response is empty.";

  result.message = null;
  return { json: result };
}

const text = candidate.trim();

// --------------------------------------------------
// 2. Character length validation
// --------------------------------------------------

if (text.length > (mode === "input" ? 4000 : 3500)) {
  result.rejection_reason =
    mode === "input"
      ? "Message exceeds the 4,000-character limit."
      : "Generated response exceeds the supported response length.";

  result.message = null;
  return { json: result };
}

// --------------------------------------------------
// 3. Unsupported control character detection
// --------------------------------------------------

if (/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(text)) {
  result.rejection_reason =
    "Text contains unsupported control characters.";

  result.message = null;
  return { json: result };
}

// --------------------------------------------------
// 4. Secret and credential detection
// --------------------------------------------------

const secretPatterns = [
  /\bAKIA[0-9A-Z]{16}\b/i,
  /\bASIA[0-9A-Z]{16}\b/i,
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/i,
  /\bBearer\s+[A-Za-z0-9._~+\/=-]{20,}/i,
  /\b(password|passwd|secret|api[_-]?key|access[_-]?token)\s*[:=]\s*\S+/i
];

if (secretPatterns.some(pattern => pattern.test(text))) {
  result.secret_detected = true;
  result.rejection_reason =
    "Text appears to contain a credential or secret.";

  result.message = null;
  result.guardrail_state.blocked = true;

  return { json: result };
}

// --------------------------------------------------
// 5. PII detection
// --------------------------------------------------

// Email addresses and long numeric sequences.
const piiPatterns = [
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i,
  /\b\d{13,19}\b/
];

// Remove standard date formats before checking
// for phone-number patterns.
//
// Supported examples:
// 2026-11-12
// 2026/11/12
// 12/11/2026

const textWithoutDates = text.replace(
  /\b(?:19|20)\d{2}[-/.](?:0?[1-9]|1[0-2])[-/.](?:0?[1-9]|[12]\d|3[01])\b/g,
  " "
);

// Detect phone-like sequences.
// Require at least 10 digits to reduce false positives
// from dates and short business identifiers.

const phoneCandidates =
  textWithoutDates.match(/\b\+?\d[\d\s().-]{7,}\d\b/g) || [];

const phoneDetected = phoneCandidates.some(candidate => {
  const digitCount = (candidate.match(/\d/g) || []).length;

  return digitCount >= 10;
});

const piiDetected =
  piiPatterns.some(pattern => pattern.test(text)) ||
  phoneDetected;

// --------------------------------------------------
// 6. Handle detected PII
// --------------------------------------------------

if (piiDetected) {
  result.pii_detected = true;
  result.input_valid = true;
  result.requires_review = true;

  result.guardrail_status = "REVIEW_REQUIRED";
  result.guardrail_decision = "REVIEW_REQUIRED";

  result.rejection_reason =
    "Text appears to contain personal information requiring review.";

  result.guardrail_state.review_required = true;
  result.message = text;

  return { json: result };
}

// --------------------------------------------------
// 7. Prompt injection detection (input only)
// --------------------------------------------------

if (mode === "input") {
  const injectionPatterns = [
    /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
    /reveal\s+(your\s+)?(system\s+prompt|hidden\s+instructions)/i,
    /act\s+as\s+(an?\s+)?(unrestricted|unfiltered)\s+(ai|assistant)/i,
    /bypass\s+(the\s+)?(security|guardrails|restrictions)/i,
    /developer\s+message\s*:/i
  ];

  if (injectionPatterns.some(pattern => pattern.test(text))) {
    result.rejection_reason =
      "The message appears to contain instructions that attempt to override system safeguards.";

    result.message = null;
    result.guardrail_state.blocked = true;

    return { json: result };
  }
}

// --------------------------------------------------
// 8. Passed validation
// --------------------------------------------------

result.message = text;

if (mode === "output") {
  result.response = text;

  if (typeof input.output === "string") {
    result.output = text;
  }
}

result.input_valid = true;
result.guardrail_status = "PASSED";
result.guardrail_decision = "PASSED";
result.guardrail_state.passed = true;

return { json: result };
